using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.USR.Marcas{    [SwaggerSchema("Modelo de lectura de un Marca")]    [GraphQLDescription("Objeto que representa un Marca existente.")]    public class clReadMarcas    {        [SwaggerSchema("Identificador único del Marca")]        [GraphQLDescription("Identificador único del Marca")]        public int? MarcaID { get; set; }        [SwaggerSchema("Marca")]        [GraphQLDescription("Marca")]        public string? Marca { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un Marca")]    [GraphQLDescription("Input para crear un Marca.")]    public class clCreateMarcas    {        [GraphQLNonNullType] [SwaggerSchema("Marca")]        [GraphQLDescription("Marca")]        public string Marca { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un Marca")]    [GraphQLDescription("Input para actualizar parcialmente un Marca.")]    public class clUpdateMarcas    {        [SwaggerSchema("Identificador único del Marca")]        [GraphQLDescription("Identificador único del Marca")]        public int? MarcaID { get; set; }        [SwaggerSchema("Marca")]        [GraphQLDescription("Marca")]        public string? Marca { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}